function normValue(v){if(typeof v==="number")return v;var t=String(v).trim();if(t.indexOf("-")>0){var p=t.split("-",2);return Math.floor((Number(p[0])+Number(p[1]))/2);}if(t.indexOf("> ")===0)return Number(t.slice(2));return Number(t.replace(",","."));}
